// Auto-population of company data.
//
// Sources, in order of preference:
//   1. data/companies/<TICKER>.json  – generated by the scheduled GitHub Action (SEC EDGAR + daily price).
//   2. Financial Modeling Prep API    – optional, user supplies a free API key in Settings (works instantly from the browser).
// Everything is normalized into the same shape so the UI never cares where it came from.

import { db } from './db.js';

let tickerIndex = null;

/** Ticker list for autocomplete (generated by the Action from SEC's company_tickers.json). */
export async function loadTickerIndex() {
  if (tickerIndex) return tickerIndex;
  try {
    const r = await fetch('data/tickers.json', { cache: 'no-cache' });
    if (!r.ok) throw new Error(r.status);
    const j = await r.json();
    // compact format: [[ticker, name, cik, exchange], ...]
    tickerIndex = (j.data || j).map(([t, n, c, x]) => ({ ticker: t, name: n, cik: c, exchange: x || '' }));
  } catch {
    tickerIndex = [];
  }
  return tickerIndex;
}

export async function suggestTickers(q, limit = 8) {
  const idx = await loadTickerIndex();
  q = q.trim().toUpperCase();
  if (!q) return [];
  const exact = [], starts = [], nameHit = [];
  for (const it of idx) {
    if (it.ticker === q) exact.push(it);
    else if (it.ticker.startsWith(q)) starts.push(it);
    else if (q.length > 2 && it.name.toUpperCase().includes(q)) nameHit.push(it);
    if (exact.length + starts.length > limit * 3 && nameHit.length > limit) break;
  }
  starts.sort((a, b) => a.ticker.length - b.ticker.length);
  return [...exact, ...starts, ...nameHit].slice(0, limit);
}

async function fetchRepo(ticker) {
  try {
    const r = await fetch(`data/companies/${encodeURIComponent(ticker.toUpperCase())}.json`, { cache: 'no-cache' });
    if (!r.ok) return null;
    const j = await r.json();
    j.source ||= 'SEC EDGAR (repo)';
    return j;
  } catch { return null; }
}

async function fmp(path, key) {
  const sep = path.includes('?') ? '&' : '?';
  const r = await fetch(`https://financialmodelingprep.com/stable/${path}${sep}apikey=${encodeURIComponent(key)}`);
  if (!r.ok) throw new Error(`FMP ${path.split('?')[0]}: HTTP ${r.status}`);
  const j = await r.json();
  if (j && j['Error Message']) throw new Error(j['Error Message']);
  return j;
}

async function fetchFMP(ticker, key) {
  const T = encodeURIComponent(ticker.toUpperCase());
  const [profile, inc, bal, cf] = await Promise.all([
    fmp(`profile?symbol=${T}`, key),
    fmp(`income-statement?symbol=${T}&limit=10`, key).catch(() => []),
    fmp(`balance-sheet-statement?symbol=${T}&limit=10`, key).catch(() => []),
    fmp(`cash-flow-statement?symbol=${T}&limit=10`, key).catch(() => []),
  ]);
  const p = Array.isArray(profile) ? profile[0] : profile;
  if (!p) return null;
  const byYear = {};
  const row = fy => (byYear[fy] ||= { fy: Number(fy) });
  for (const x of inc || []) Object.assign(row(x.fiscalYear || x.calendarYear || String(x.date).slice(0, 4)), {
    end: x.date, revenue: x.revenue, grossProfit: x.grossProfit, operatingIncome: x.operatingIncome,
    netIncome: x.netIncome, eps: x.eps, epsDiluted: x.epsDiluted ?? x.epsdiluted, shares: x.weightedAverageShsOutDil,
  });
  for (const x of bal || []) Object.assign(row(x.fiscalYear || x.calendarYear || String(x.date).slice(0, 4)), {
    totalAssets: x.totalAssets, totalLiabilities: x.totalLiabilities, equity: x.totalStockholdersEquity,
    cash: x.cashAndCashEquivalents, debt: x.totalDebt,
  });
  for (const x of cf || []) Object.assign(row(x.fiscalYear || x.calendarYear || String(x.date).slice(0, 4)), {
    ocf: x.operatingCashFlow ?? x.netCashProvidedByOperatingActivities, capex: x.capitalExpenditure != null ? Math.abs(x.capitalExpenditure) : undefined,
    dividendsPaid: x.commonDividendsPaid ?? x.dividendsPaid, buybacks: x.commonStockRepurchased,
  });
  const annual = Object.values(byYear).sort((a, b) => a.fy - b.fy);
  annual.forEach(a => { if (a.ocf != null && a.capex != null) a.fcf = a.ocf - a.capex; });
  return {
    ticker: p.symbol, name: p.companyName, exchange: p.exchange || p.exchangeShortName, sector: p.sector, industry: p.industry,
    country: p.country, website: p.website, description: p.description, ceo: p.ceo, employees: p.fullTimeEmployees,
    cik: p.cik, price: { last: p.price, date: new Date().toISOString().slice(0, 10), changePct: p.changePercentage ?? p.changes },
    marketCap: p.marketCap ?? p.mktCap, beta: p.beta,
    financials: { annual },
    source: 'Financial Modeling Prep', fetchedAt: new Date().toISOString(),
  };
}

/** Fetch the freshest available data for a ticker. Returns normalized object or null. */
export async function fetchCompanyData(ticker, { preferLive = false } = {}) {
  const key = await db.getKV('fmpKey', '');
  const repo = await fetchRepo(ticker);
  if (key && (preferLive || !repo)) {
    try {
      const live = await fetchFMP(ticker, key);
      if (live) {
        // repo data (SEC) may contain longer history / SIC sector; keep the richest financials
        if (repo?.financials?.annual?.length > (live.financials.annual?.length || 0)) live.financials = repo.financials;
        return live;
      }
    } catch (e) { console.warn('FMP failed', e); if (!repo) throw e; }
  }
  return repo;
}

/** Merge fetched data into a company record without clobbering the user's own edits. */
export function applyAutoData(company, data) {
  if (!data) return company;
  const fill = (k, v) => { if (v != null && v !== '' && (company[k] == null || company[k] === '')) company[k] = v; };
  fill('name', data.name); fill('sector', data.sector); fill('industry', data.industry); fill('exchange', data.exchange);
  fill('country', data.country); fill('website', data.website); fill('description', data.description); fill('cik', data.cik);
  company.auto = {
    price: data.price || company.auto?.price || null,
    marketCap: data.marketCap ?? null,
    sharesOutstanding: data.sharesOutstanding ?? null,
    financials: data.financials || company.auto?.financials || { annual: [] },
    fiscalYearEnd: data.fiscalYearEnd, sic: data.sic, employees: data.employees, ceo: data.ceo, beta: data.beta,
    priceHistory: data.priceHistory || company.auto?.priceHistory || null,
    filings: data.filings || company.auto?.filings || [],
    source: data.source, fetchedAt: data.fetchedAt || new Date().toISOString(),
  };
  // remember price snapshots so the app builds its own history over time
  const p = company.auto.price;
  if (p?.last && p?.date) {
    company.priceLog ||= [];
    if (!company.priceLog.some(x => x.date === p.date)) company.priceLog.push({ date: p.date, price: p.last });
    company.priceLog = company.priceLog.slice(-400);
  }
  return company;
}

/** Background refresh: pull newer repo snapshots (cheap) and, if a key is configured, stale live data (rate-limited). */
export async function refreshAll({ onProgress } = {}) {
  const companies = await db.all('companies');
  const key = await db.getKV('fmpKey', '');
  let updated = 0, liveCalls = 0;
  for (const c of companies) {
    if (c.autoUpdate === false) continue;
    const prev = c.auto?.fetchedAt ? Date.parse(c.auto.fetchedAt) : 0;
    let data = await fetchRepo(c.ticker);
    const stale = Date.now() - prev > 3 * 864e5;
    if (key && stale && liveCalls < 15 && (!data || Date.parse(data.fetchedAt || 0) <= prev)) {
      try { data = (await fetchFMP(c.ticker, key)) || data; liveCalls++; } catch (e) { console.warn(e); }
    }
    if (data && Date.parse(data.fetchedAt || 0) > prev) {
      applyAutoData(c, data);
      await db.put('companies', c, { silent: true });
      updated++;
    }
    onProgress?.(c);
  }
  await db.setKV('lastRefresh', Date.now());
  return updated;
}

// ---- Derived metrics -----------------------------------------------------

const last = a => (a && a.length ? a[a.length - 1] : undefined);
const div = (a, b) => (a == null || b == null || !b ? null : a / b);

export function metrics(company) {
  const fin = company.auto?.financials?.annual || [];
  const L = last(fin) || {};
  const P = fin.length > 1 ? fin[fin.length - 2] : {};
  const price = company.manualPrice ?? company.auto?.price?.last ?? null;
  const shares = company.auto?.sharesOutstanding || L.shares || null;
  const marketCap = company.auto?.marketCap || (price && shares ? price * shares : null);
  const eps = L.epsDiluted ?? L.eps ?? div(L.netIncome, L.shares);
  const fcf = L.fcf ?? (L.ocf != null && L.capex != null ? L.ocf - L.capex : null);
  const firstRev = fin.find(x => x.revenue)?.revenue;
  const firstRevYear = fin.find(x => x.revenue)?.fy;
  const years = L.fy && firstRevYear ? L.fy - firstRevYear : 0;
  const fair = company.fairValue ? Number(company.fairValue) : null;
  return {
    price, marketCap, eps, fcf,
    fy: L.fy,
    revenue: L.revenue, netIncome: L.netIncome,
    revGrowth: div(L.revenue, P.revenue) != null ? L.revenue / P.revenue - 1 : null,
    revCagr: years > 0 && firstRev > 0 && L.revenue > 0 ? Math.pow(L.revenue / firstRev, 1 / years) - 1 : null,
    cagrYears: years,
    grossMargin: div(L.grossProfit, L.revenue),
    opMargin: div(L.operatingIncome, L.revenue),
    netMargin: div(L.netIncome, L.revenue),
    fcfMargin: div(fcf, L.revenue),
    roe: div(L.netIncome, L.equity),
    debtToEquity: div(L.debt, L.equity),
    pe: price && eps > 0 ? price / eps : null,
    pfcf: marketCap && fcf > 0 ? marketCap / fcf : null,
    ps: marketCap && L.revenue ? marketCap / L.revenue : null,
    fcfYield: marketCap && fcf != null ? fcf / marketCap : null,
    upside: price && fair ? fair / price - 1 : null,
  };
}
